import React from 'react';
import { SpriteImage } from './SpriteImage';
import manifestData from '../generated/sprite-manifest.json';

// Simple check to see if an image exists in manifest
const MANIFEST_KEYS = new Set(Object.keys(manifestData));

;

const DEFAULT_WIDTHS = [320, 640, 1024];

function getBase(src) {
  const m = src.match(/(img-[a-f0-9]+)-\d+\.(webp|avif|jpe?g)$/i);
  if (m) return m[1];
  // fallback: try to remove trailing -640.webp etc
  const m2 = src.match(/(images\/optimized\/[a-z0-9\-]+)-\d+\.(webp|avif|jpe?g)$/i);
  if (m2) return m2[1].split('/').pop();
  return null;
}

export default function ResponsiveImage({ src, alt = '', className = '', sizes, loading = 'lazy', priority = false, decoding = 'async' }) {
  const base = getBase(src);
  const useSizes = sizes || '(max-width: 640px) 100vw, 33vw';

  // --- SPRITE LOGIC ---
  if (base) {
    // Try to find the best sprite candidate.
    // For simplicity, we prefer the 1024px version as the "master" for sprites to ensure quality on all screens.
    // Ideally we would select based on breakpoint, but CSS-only sprite switching is complex.
    // Loading the 1024px sprite version is safe because the cost is in downloading the Sheet, not the region.
    // And standard desktop sheet will be loaded anyway.

    // Check if 1024 exists, else 640, else 320.
    const candidates = ['1024', '640', '320'];
    let bestKey = null;

    for (const w of candidates) {
      const key = `${base}-${w}.webp`;
      if (MANIFEST_KEYS.has(key)) {
        bestKey = key;
        break;
      }
    }

    if (bestKey) {
      // Detected object-fit mode from className
      const isCover = className.includes('object-cover');
      const isContain = className.includes('object-contain');

      return (
        <SpriteImage
          imageId={bestKey}
          alt={alt}
          className={className}
          cover={isCover}
          contain={isContain}
          loading={priority ? 'eager' : loading}
          decoding={decoding}
        />
      );
    }
  }
  // --- END SPRITE LOGIC ---

  if (!base) {
    // fallback to simple img
    return (
      <img
        src={src}
        alt={alt}
        className={className}
        loading={priority ? 'eager' : loading}
        decoding={decoding}
        {...(priority ? { fetchPriority: 'high' } : {})}
      />
    );
  }

  const avifSrcSet = DEFAULT_WIDTHS.map((w) => `/images/optimized/${base}-${w}.avif ${w}w`).join(', ');
  const webpSrcSet = DEFAULT_WIDTHS.map((w) => `/images/optimized/${base}-${w}.webp ${w}w`).join(', ');
  const jpegSrcSet = DEFAULT_WIDTHS.map((w) => `/images/optimized/${base}-${w}.jpeg ${w}w`).join(', ');

  const fallback = `/images/optimized/${base}-640.jpeg`;

  return (
    <picture>
      <source type="image/avif" srcSet={avifSrcSet} sizes={useSizes} />
      <source type="image/webp" srcSet={webpSrcSet} sizes={useSizes} />
      <img
        src={fallback}
        srcSet={jpegSrcSet}
        sizes={useSizes}
        alt={alt}
        className={className}
        loading={priority ? 'eager' : loading}
        decoding={decoding}
        {...(priority ? { fetchPriority: 'high' } : {})}
      />
    </picture>
  );
}
